 code:'#include <stdio.h>\n\ntypedef struct {\n    int id;\n    char name[32];\n} Row;\n\nint main(void) {\n    Row row = {0, ""};\n    // TODO: read the two fields from stdin.\n    printf("%d | %s\\n", row.id, row.name);\n    return 0;\n}\n',solution:'#include <stdio.h>\ntypedef struct {int id;char name[32];} Row;\nint main(void){Row r;if(scanf("%d %31s",&r.id,r.name)!=2)return 1;printf("%d | %s\\n",r.id,r.name);return 0;}',input:'1 Ada',tests:[{name:'First row',input:'1 Ada',expected:'1 | Ada'},{name:'Another row',input:'42 Grace',expected:'42 | Grace'}]
